<section class="page-heading"><div><p class="eyebrow">ORGANISEZ VOS PIÈCES PAR AMBIANCE OU OCCASION</p><h1>Mes collections</h1><p class="subheading">Une même pièce peut figurer dans plusieurs collections.</p></div></section>
<div class="collection-grid"><?php foreach($collections as $collection): ?><a class="collection-card" href="<?= e(url('collection-show',['id'=>$collection['id']])) ?>"><span class="collection-symbol">▤</span><small><?= e($collection['item_count']) ?> pièce<?= $collection['item_count']>1?'s':'' ?></small><h2><?= e($collection['name']) ?></h2><p><?= e($collection['description']) ?></p></a><?php endforeach; ?><article class="collection-card collection-create"><h2>Nouvelle collection</h2><form method="post" action="<?= e(url('collection-save')) ?>"><?= csrf_field() ?><label>Nom<input name="name" maxlength="120" required placeholder="Ex. Tenues de soirée"></label><label>Description<textarea name="description" rows="2"></textarea></label><div class="multi-select"><b>Ajouter des vêtements</b><?php foreach($clothes as $item): ?><label><input type="checkbox" name="items[]" value="<?= e($item['id']) ?>"> <?= e($item['name']) ?></label><?php endforeach; ?></div><button class="button primary">Créer la collection <span>→</span></button></form></article></div>
